    floorText('COCKPIT MANIPULATOR', -26.6, 5.2, 4.6, { size: 34, weight: 600, colorKey: 'textDim', letter: 2 });
    // Battery manipulator at TL5 (from drawing: "added for use in ZS32 HEV")
