      const hit = new THREE.Mesh(new THREE.BoxGeometry(1.4, 2.8, 1.4), new THREE.MeshBasicMaterial({ visible: false })); hit.position.set(0, 1.4, 0); hit.userData = { kind: 'scanner', id }; g.add(hit); pickables.push(hit);
