      const hit = new THREE.Mesh(new THREE.BoxGeometry(1.2, 2, 1.2), new THREE.MeshBasicMaterial({ visible: false })); hit.position.set(0, 1, 0); hit.userData = { kind: 'scanner', id }; g.add(hit); pickables.push(hit);
